import{Z as r,e as t,f as o,a0 as s}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Saved Reports and Scheduled Delivery","description":"","frontmatter":{},"headers":[],"relativePath":"guides/submissions-workflows/saved-reports-and-scheduled-delivery.md","filePath":"guides/submissions-workflows/saved-reports-and-scheduled-delivery.md","lastUpdated":1782912477000}'),a={name:"guides/submissions-workflows/saved-reports-and-scheduled-delivery.md"};function n(i,e,d,l,p,h){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="saved-reports-and-scheduled-delivery" tabindex="-1">Saved Reports and Scheduled Delivery <a class="header-anchor" href="#saved-reports-and-scheduled-delivery" aria-label="Permalink to &quot;Saved Reports and Scheduled Delivery&quot;">​</a></h1><p>Reports are saved analytical views over submissions. When you need the same export every week — not a one-off download from the submissions index — save a report and optionally attach scheduled email delivery.</p><p>This guide is a <strong>getting-started walkthrough</strong>. For export formats, large-export behaviour, permissions, project config, cron details, incremental windows, and troubleshooting, see <a href="/reports/reports">Reports overview</a> and <a href="/reports/scheduled-reports">Scheduled reports</a>.</p><h2 id="prepare-a-weekly-enquiry-report" tabindex="-1">Prepare a Weekly Enquiry Report <a class="header-anchor" href="#prepare-a-weekly-enquiry-report" aria-label="Permalink to &quot;Prepare a Weekly Enquiry Report&quot;">​</a></h2><p>Use a contact form that already has a few completed test submissions. You need permission to manage reports and scheduled reports, a working mail transport, and access to the server scheduler (or help from the person who manages hosting).</p><p>In this example, name the report <strong>Weekly Enquiries</strong>, select your contact form and include its submission date and email field as columns. Send the report to a test mailbox you control while configuring delivery. The <a href="/reports/reports">Reports overview</a> explains the available filters and columns.</p><h2 id="when-to-use-a-report" tabindex="-1">When to Use a Report <a class="header-anchor" href="#when-to-use-a-report" aria-label="Permalink to &quot;When to Use a Report&quot;">​</a></h2><p>Use the <strong>submissions index</strong> for day-to-day review, editing, and status changes. Use a <strong>saved report</strong> when you need a reusable filter set, on-demand export in multiple formats, or recurring email delivery. See <a href="/reports/reports#reports-vs-the-submissions-index">Reports vs the submissions index</a>.</p><h2 id="step-1-create-and-run-a-saved-report" tabindex="-1">Step 1: Create and Run a Saved Report <a class="header-anchor" href="#step-1-create-and-run-a-saved-report" aria-label="Permalink to &quot;Step 1: Create and Run a Saved Report&quot;">​</a></h2><ol><li>Go to <strong>Formie → Reports</strong> → <strong>New Report</strong>.</li><li>Configure <strong>General</strong> (name, handle, forms), <strong>Filters</strong>, <strong>Columns</strong>, <strong>Display</strong>, and <strong>Export</strong> — see <a href="/reports/reports#what-a-report-includes">What a report includes</a>.</li><li>Save and run the report. Confirm the summary, chart, and table match what you expect.</li><li>Use <strong>Export</strong> for a one-off download. Pick the format your team needs — <a href="/reports/reports#export-formats">Export formats</a>.</li></ol><p>If the export is large, Formie queues it in the background — see <a href="/reports/reports#large-exports">Large exports</a>.</p><h2 id="step-2-schedule-email-delivery" tabindex="-1">Step 2: Schedule Email Delivery <a class="header-anchor" href="#step-2-schedule-email-delivery" aria-label="Permalink to &quot;Step 2: Schedule Email Delivery&quot;">​</a></h2><p>Scheduled reports email a summary plus an export attachment on a daily or weekly cadence.</p><ol><li>Ensure server cron runs <code>./craft formie/cron/run</code> — typically hourly. See <a href="/reports/scheduled-reports#before-you-start-cron">Before you start: cron</a>.</li><li>Create and save a report first, then open <strong>Settings → Scheduled Reports</strong> (or the report&#39;s <strong>Scheduled</strong> tab) and choose <strong>New Scheduled Report</strong>.</li><li>Link the report, set <strong>Schedule</strong> (frequency, day, hour), and <strong>Delivery</strong> (file type, recipients, optional subject/message). See <a href="/reports/scheduled-reports#creating-a-scheduled-report">Creating a scheduled report</a>.</li><li><strong>Save</strong>, then use <strong>Send Test Email</strong> to inspect the summary and attachment in your own mailbox. The test goes to the acting user, not the configured recipients. Check recipient addresses separately and confirm the first scheduled delivery reaches them.</li></ol><p>After the first successful delivery, attachments use an <strong>incremental window</strong> — submissions since the previous send. See <a href="/reports/scheduled-reports#incremental-export-windows">Incremental export windows</a>.</p><h2 id="checklist-before-go-live" tabindex="-1">Checklist Before Go-Live <a class="header-anchor" href="#checklist-before-go-live" aria-label="Permalink to &quot;Checklist Before Go-Live&quot;">​</a></h2><ul><li>Cron job registered and <code>./craft formie/cron/run</code> runs without errors</li><li>Test email received with expected summary and attachment</li><li>Confirm the configured recipient addresses and user group are authorised to receive the exported data. Email recipients do not need Craft report permissions; those permissions govern control-panel actions, not receipt of attachments.</li><li>Report and schedule settings deployed via project config to staging/production</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>Work through <a href="/reports/scheduled-reports#troubleshooting">Scheduled reports — Troubleshooting</a> for empty attachments, cron vs test-email mismatches, and attachment size limits.</p>',19)])])}const m=r(a,[["render",n]]);export{u as __pageData,m as default};
